// Compute the time window (last 24h, Slack uses Unix timestamp seconds with microsecond suffix).

const now = Math.floor(Date.now() / 1000);
const oldest = now - 24 * 60 * 60;

return [{ json: {
  oldest: String(oldest),
  latest: String(now),
  windowHours: 24,
  channel: $env.SLACK_SOURCE_CHANNEL,
  digestChannel: $env.SLACK_DIGEST_CHANNEL,
  provider: ($env.SLACK_DIGEST_PROVIDER || 'openai').toLowerCase(),
} }];

// Reduce the Slack history payload into a compact text-only conversation log
// the LLM can summarize. Drops bot messages, threads, file uploads.

const input = $input.first().json;

if (!input.ok) {
  throw new Error('Slack API error: ' + (input.error || 'unknown'));
}

const messages = (input.messages || [])
  .filter(m => m.type === 'message')
  .filter(m => !m.subtype || ['thread_broadcast'].includes(m.subtype))
  .filter(m => m.text && m.text.length > 5);

if (messages.length === 0) {
  return [{ json: { skipped: true, reason: 'no messages in window' } }];
}

// Reverse chronological order from Slack, flip to oldest-first for the LLM
const sorted = [...messages].sort((a, b) => parseFloat(a.ts) - parseFloat(b.ts));

// Compact text format: <user-id>: <text>
const transcript = sorted.map(m => {
  const user = m.user || 'unknown';
  const text = (m.text || '').replace(/<@[A-Z0-9]+>/g, '@user').replace(/<#[A-Z0-9]+\|([^>]+)>/g, '#$1');
  return `${user}: ${text}`;
}).join('\n');

// Token-cap: rough rule, 4 chars per token, keep under 6000 tokens for the LLM
const MAX_CHARS = 24000;
const capped = transcript.length > MAX_CHARS
  ? '... (older messages truncated) ...\n' + transcript.slice(-MAX_CHARS)
  : transcript;

const window = ($('Compute Time Window').first() && $('Compute Time Window').first().json) || {};

return [{ json: {
  messageCount: sorted.length,
  transcript: capped,
  window: {
    hours: window.windowHours || 24,
    digestChannel: window.digestChannel,
  },
  provider: window.provider || 'openai',
} }];

// Build the LLM prompt. System prompt encourages bullet-style summary,
// no marketing fluff, factual.

const input = $input.first().json;

const systemPrompt = [
  'You are a digest writer. Read the team chat transcript below and produce a short summary.',
  'Format: 4-7 bullet points, factual, mention names of people involved per topic.',
  'No marketing language. No filler. No headers. No emoji unless one is in the transcript.',
  'If the transcript is mostly noise (greetings, no decisions), say so in one sentence.',
].join(' ');

const userPrompt = `Last ${input.window.hours}h chat. ${input.messageCount} messages.\n\n${input.transcript}\n\nWrite the digest now.`;

return [{ json: {
  ...input,
  systemPrompt,
  userPrompt,
} }];

// Normalize the LLM response shape. OpenAI returns {choices:[{message:{content}}]},
// Anthropic returns {content:[{type:'text',text}]}.

const input = $input.first().json;

let replyText = '';
if (input.choices && input.choices[0] && input.choices[0].message) {
  replyText = input.choices[0].message.content || '';
} else if (input.content && Array.isArray(input.content) && input.content[0]) {
  replyText = input.content[0].text || '';
} else if (input.text) {
  replyText = input.text;
} else {
  replyText = '(no reply)';
}

const window = ($('Build Transcript').first() && $('Build Transcript').first().json) || {};

return [{ json: {
  digest: replyText,
  messageCount: window.messageCount || 0,
  digestChannel: (window.window && window.window.digestChannel) || $env.SLACK_DIGEST_CHANNEL,
  generatedAt: new Date().toISOString(),
} }];

// Discriminate between LLM-error and Router-fallback so the structured error
// log this Code node emits does not leak the system prompt + transcript.
//
// Router-fallback = unknown provider value (typo, env var not set). The Code
// node here emits a clear diagnostic without serializing $json.
// LLM-error = the OpenAI / Anthropic Reply node failed (rate limit, 5xx,
// timeout). The Code node here emits err.message + err.httpCode but does NOT
// echo the prompt back.
//
// IMPORTANT scoping: this discriminator only protects what THIS Code node
// writes. n8n's execution-data store still has the upstream nodes' input pins
// (including systemPrompt + transcript) unless you set workflow Settings to
// `Save Execution Progress: errored only` and apply your own redaction
// policy. Do that on the operator side for full prompt-privacy.

const input = $input.first();
const err = (input.json && input.json.error) || {};
const httpCode = err.httpCode || (err.response && err.response.status) || null;

// Tight regex: 429 / 5xx / timeout / connection-reset / abort. Avoids the
// false-positive of literally matching the digit '5' anywhere in err.message.
const llmErrorRe = /^(429|5\d\d)\b|\b(timeout|ECONNRESET|ECONNABORTED|ETIMEDOUT|abort)\b/i;
const isHttp5xxOr429 = httpCode === 429 || (httpCode >= 500 && httpCode < 600);
const isLlmError = isHttp5xxOr429 || (err.message && llmErrorRe.test(err.message))
  || err.name === 'AxiosError' || err.name === 'NodeApiError';
const isRouterFallback = !isLlmError && (!err || !err.message);

const window = ($('Build Transcript').first() && $('Build Transcript').first().json) || {};
const originalProvider = window.provider || 'unknown';

let diagnostic;
let errorClass;
if (isRouterFallback) {
  diagnostic = `Unknown provider value: "${originalProvider}". Set SLACK_DIGEST_PROVIDER to openai or anthropic.`;
  errorClass = 'router-fallback';
} else {
  // Log only the LLM-side error message, never the prompt or transcript.
  diagnostic = (err.message || 'LLM call failed').slice(0, 240);
  errorClass = 'llm-error';
}

return [{ json: {
  digest: '(digest could not be generated)',
  fallback: true,
  errorClass,
  diagnostic,
  httpCode,
  provider: originalProvider,
  messageCount: window.messageCount || 0,
  digestChannel: (window.window && window.window.digestChannel) || $env.SLACK_DIGEST_CHANNEL,
  generatedAt: new Date().toISOString(),
} }];
